                fs.writeFileSync(filePath, content, 'utf8');
                console.log(`Updated: ${filePath}`);
            }
        } catch (err) {
            console.error(`Error processing ${filePath}:`, err);
        }
    });
} catch (err) {
    console.error('Walk failed:', err);
}
